INSERT INTO products VALUES
('pn-withus-steel-22', 'KR:KOSDAQ:024940', '위더스 통3중 스텐우드 IH 프라이팬', 'PN풍년', 'FRYING_PAN', 'KR', 'VERIFIED', '{"id":"pn-withus-steel-22","symbol":"024940","name":"위더스 통3중 스텐우드 IH 프라이팬","brand":"PN풍년","category":"FRYING_PAN","market":"KR","relation":"MANUFACTURER","size":"22 cm · WSFP-22(IH)","prep":"조리 표면","source":"https://m.lotteimall.com/goods/viewGoodsDetail.lotte?goods_no=2984040213","status":"VERIFIED","facts":[],"evidence":[{"title":"스테인리스 몸체 사양","summary":"판매처에 몸체는 통3중 스테인리스 스틸, 손잡이는 스테인리스와 비치우드라고 기재되어 있습니다. 코팅 성분은 공개 사양에서 확인되지 않습니다.","source":"https://m.lotteimall.com/goods/viewGoodsDetail.lotte?goods_no=2984040213"}],"material":"통3중 스테인리스 스틸 몸체","description":"PN풍년이 제조한 22 cm 인덕션용 프라이팬입니다."}'),
('cuckoo-twin-pressure-10', 'KR:KOSPI:192400', '트윈프레셔 올스테인리스 내솥 밥솥', '쿠쿠전자', 'RICE_COOKER', 'KR', 'VERIFIED', '{"id":"cuckoo-twin-pressure-10","symbol":"192400","name":"트윈프레셔 올스테인리스 내솥 밥솥","brand":"쿠쿠전자","category":"RICE_COOKER","market":"KR","relation":"OWNER","size":"10인용 · 1.8 L · CRP-KHTAS1010FWM","prep":"취사 내솥","source":"https://www.cuckoo.co.kr/mall/productView?productNo=5856","status":"VERIFIED","facts":[],"evidence":[{"title":"내솥 소재","summary":"공식 제품 페이지와 사용설명서에 올스테인리스 내솥을 사용하는 10인용 IH 전기압력밥솥으로 안내되어 있습니다.","source":"https://cdn.cuckoo.co.kr/upload_cuckoo/_bo_rep/manual/file_45591d28-7e07-4238-b4b1-037d5a9713c4.pdf"},{"title":"제조사와 상장사 관계","summary":"쿠쿠전자가 제조하며, 쿠쿠홀딩스 사업보고서에 쿠쿠전자 보유 지분이 100%로 기재되어 있습니다.","source":"https://kind.krx.co.kr/external/2026/03/16/002187/20260316006221/11011.htm"}],"material":"올스테인리스 내솥","description":"쿠쿠홀딩스의 자회사 쿠쿠전자에서 판매하는 10인용 트윈프레셔 밥솥입니다."}'),
('coway-icon-2', 'KR:KOSPI:021240', '아이콘 정수기 2', '코웨이', 'WATER_FILTER', 'KR', 'VERIFIED', '{"id":"coway-icon-2","symbol":"021240","name":"아이콘 정수기 2","brand":"코웨이","category":"WATER_FILTER","market":"KR","relation":"MANUFACTURER","size":"CHP-7211N · 냉온정수기","prep":"가정용 직수 정수기","source":"https://www.coway.com/product/detail?optno=6&prdno=1494","status":"VERIFIED","facts":[],"evidence":[{"title":"정수 필터 구성","summary":"이 모델의 공식 자료에 나노트랩 필터와 이노센스 필터가 기재되어 있습니다.","source":"https://www.coway.com/product/detail?optno=6&prdno=1494"},{"title":"음용수 PFAS 저감 확인 기준","summary":"미국 환경보호청은 제품과 필터 모델별 인증 정보를 확인하라고 안내합니다. 이 모델의 PFAS 저감 인증은 아래 제조사 자료에서 확인되지 않습니다.","source":"https://www.epa.gov/water-research/identifying-drinking-water-filters-certified-reduce-pfas"}],"material":"나노트랩 필터와 이노센스 필터","description":"나노트랩 필터와 이노센스 필터를 사용하는 코웨이의 가정용 냉온정수기입니다."}'),
('lg-puricare-hit', 'KR:KOSPI:066570', '퓨리케어 360° 공기청정기 Hit', 'LG전자', 'AIR_PURIFIER', 'KR', 'VERIFIED', '{"id":"lg-puricare-hit","symbol":"066570","name":"퓨리케어 360° 공기청정기 Hit","brand":"LG전자","category":"AIR_PURIFIER","market":"KR","relation":"MANUFACTURER","size":"62 m² · AS186HWWA","prep":"가정용 실내 공기청정기","source":"https://www.lge.co.kr/product/air-purifier/as186hwwa","status":"VERIFIED","facts":[],"evidence":[{"title":"청정 사용 면적과 입자 여과","summary":"제조사가 청정 사용 면적을 62 m²로 표기합니다. 공기 중 입자 여과 시험은 별도로 명시된 시험 조건에서 진행되었습니다.","source":"https://www.lge.co.kr/product/air-purifier/as186hwwa"},{"title":"실내 공기 여과","summary":"미국 환경보호청은 공기청정기를 선택할 때 공간 크기에 맞는 입자 여과 성능을 확인하라고 안내합니다.","source":"https://www.epa.gov/indoor-air-quality-iaq/air-cleaners-and-air-filters-home"}],"material":"입자 여과 필터","description":"LG전자가 청정 사용 면적을 62 m²로 안내한 가정용 공기청정기입니다."}'),
('samsung-bluesky-5500', 'KR:KOSPI:005930', '블루스카이 5500', '삼성전자', 'AIR_PURIFIER', 'KR', 'VERIFIED', '{"id":"samsung-bluesky-5500","symbol":"005930","name":"블루스카이 5500","brand":"삼성전자","category":"AIR_PURIFIER","market":"KR","relation":"MANUFACTURER","size":"60 m² · AP70F06103RVD","prep":"가정용 실내 공기청정기","source":"https://www.samsung.com/sec/air-cleaner/air-purifier-ap70f06103rd-d2c/AP70F06103RVD/","status":"VERIFIED","facts":[],"evidence":[{"title":"청정 사용 면적과 입자 여과","summary":"제조사가 청정 사용 면적을 60 m²로 표기합니다. 센서에 표시되는 먼지 농도는 사용 환경과 계측 방법에 따라 달라질 수 있습니다.","source":"https://www.samsung.com/sec/air-cleaner/air-purifier-ap70f06103rd-d2c/AP70F06103RVD/"},{"title":"실내 공기 여과","summary":"미국 환경보호청은 공기청정기를 선택할 때 공간 크기에 맞는 입자 여과 성능을 확인하라고 안내합니다.","source":"https://www.epa.gov/indoor-air-quality-iaq/air-cleaners-and-air-filters-home"}],"material":"미세먼지 집진필터","description":"삼성전자가 청정 사용 면적을 60 m²로 안내한 가정용 공기청정기입니다."}'),
