('brita-elite-ob06', 'US:NYSE:CLX', '브리타 엘리트 교체 필터', 'Brita', 'WATER_FILTER', 'US', 'VERIFIED', '{"id":"brita-elite-ob06","symbol":"CLX","name":"브리타 엘리트 교체 필터","brand":"Brita","category":"WATER_FILTER","market":"US","relation":"OWNER","status":"VERIFIED","size":"1개 · OB06","prep":"물병·디스펜서 교체형 필터","source":"https://www.brita.com/products/brita-elite-replacement-filters/","facts":[],"evidence":[{"title":"미세플라스틱·납 저감 시험","summary":"공식 성능표는 지정된 호환 시스템에서 입경 0.5~1 μm의 미세플라스틱 99.6% 저감과 납 저감 인증 범위를 공개합니다. 표준 실험실 시험 결과입니다.","source":"https://www.brita.com/support/performance-data/brita-elite/"},{"title":"브랜드 보유 관계","summary":"미국 사업의 Brita 브랜드는 The Clorox Company가 공개한 브랜드에 포함됩니다.","source":"https://www.thecloroxcompany.com/brands/clorox-family-of-brands/"}],"material":"활성 여과 매체 · 교체식 필터","description":"미국 판매 모델 OB06입니다. 공식 자료에 명시된 Brita 물병·디스펜서 모델과 함께 사용하는 교체 필터입니다."}'),
