('ao-smith-ro-mb4000', 'US:NYSE:AOS', 'A. O. 스미스 싱크대 하부 역삼투 정수기', 'A. O. Smith', 'WATER_FILTER', 'US', 'VERIFIED', '{"id":"ao-smith-ro-mb4000","symbol":"AOS","name":"A. O. 스미스 싱크대 하부 역삼투 정수기","brand":"A. O. Smith","category":"WATER_FILTER","market":"US","relation":"MANUFACTURER","status":"VERIFIED","size":"AO-US-RO-MB-4000","prep":"싱크대 하부 설치형 역삼투 장치","source":"https://www.aosmithatlowes.com/products/water-filters/drinking-water/ao-us-ro-mb-4000/","facts":[],"evidence":[{"title":"저감 성능 시험 조건","summary":"제조사가 PFOA·PFOS 저감과 IAPMO의 지정 표준 인증을 공개합니다. 성능표에 표시된 시험 조건과 항목별 결과를 확인할 수 있습니다.","source":"https://www.aosmithatlowes.com/media/1234/ao-us-ro-mb-4000_pds.pdf"},{"title":"미국 EPA의 정수 필터 인증 안내","summary":"EPA는 해당 물질의 저감 인증과 제품별 성능표를 확인하도록 안내합니다.","source":"https://www.epa.gov/water-research/identifying-drinking-water-filters-certified-reduce-pfas"}],"material":"역삼투 막 · 카본·Claryum 필터","description":"미국 판매 모델 AO-US-RO-MB-4000입니다. 역삼투 막, 카본·Claryum 필터와 미네랄 보충 단계를 포함합니다."}'),
('pentair-everpure-4fc-ps', 'US:NYSE:PNR', '에버퓨어 QL3B 4FC-PS 여과 시스템', 'Everpure', 'WATER_FILTER', 'US', 'VERIFIED', '{"id":"pentair-everpure-4fc-ps","symbol":"PNR","name":"에버퓨어 QL3B 4FC-PS 여과 시스템","brand":"Everpure","category":"WATER_FILTER","market":"US","relation":"MANUFACTURER","status":"VERIFIED","size":"EV929830 · 4,000갤런 정격","prep":"상업용 식수 설비 설치형 필터","source":"https://flowandfiltrationsolutions.pentair.com/en-us/commercial-filtration/products/filtration-systems/pfoa-pfos-reduction-systems.html","facts":[],"evidence":[{"title":"PFOA·PFOS 저감 인증","summary":"이 모델의 공식 사양서에 PFOA·PFOS 저감에 대한 IAPMO의 NSF/ANSI 53 인증과 별도 미세플라스틱 저감 인증이 기재됩니다.","source":"https://flowandfiltrationsolutions.pentair.com/content/dam/extranet/nam/filtration/everpure/commercial/spec-sheets/pfas-reduction-spec-sheets/ev929830-ql3b-4fc-ps-spec.pdf"},{"title":"미국 EPA의 정수 필터 인증 안내","summary":"EPA는 해당 물질의 저감 인증과 제품별 성능표를 확인하도록 안내합니다.","source":"https://www.epa.gov/water-research/identifying-drinking-water-filters-certified-reduce-pfas"}],"material":"Fibredyne 여과 매체 · 일체형 카트리지","description":"미국 판매 모델 EV929830입니다. 상업용 식수·음료 설비에 연결하는 Pentair Everpure 필터 시스템입니다."}'),
('filtrete-1900', 'US:NYSE:MMM', '필트리트 MPR 1900 공조 필터', 'Filtrete', 'AIR_PURIFIER', 'US', 'VERIFIED', '{"id":"filtrete-1900","symbol":"MMM","name":"필트리트 MPR 1900 공조 필터","brand":"Filtrete","category":"AIR_PURIFIER","market":"US","relation":"MANUFACTURER","status":"VERIFIED","size":"16 × 25 × 1인치","prep":"HVAC 공조 설비용 교체형 필터","source":"https://www.3m.com/3M/en_US/p/d/b00039899/?preselect=7580431","facts":[],"evidence":[{"title":"제조사 여과 등급","summary":"제조사는 1인치 MPR 1900 필터 계열을 MERV 13 등급으로 공개합니다. 공조 장치에서 사용하는 필터의 등급입니다.","source":"https://www.3m.com/3M/en_US/p/d/b00039899/?preselect=7580431"},{"title":"미국 EPA의 실내 공기 여과 안내","summary":"EPA는 공조 필터와 이동형 공기청정기의 적용 방식이 다르며, 공조 팬·필터 슬롯과의 호환성을 확인하도록 안내합니다.","source":"https://www.epa.gov/wildfires/indoor-air-filtration"}],"material":"주름형 여과 매체","description":"미국 판매 16 × 25 × 1인치 규격입니다. 호환 공조 설비에 삽입하는 교체 필터로, 제조사 등급은 MPR 1900 및 MERV 13입니다."}');
